import sys, math, random, collections
sys.path.insert(0,'/tmp')
from load import load
qs=load()
random.seed(0)

def lognorm(x,m,s): return -0.5*((x-m)/s)**2 - math.log(s)
def llr_alg(scores, nvar):
    # correct ~ N(1.0,0.4); wrong = mix of attractor N(1.7,0.37) and singleton N(-0.45,0.72)
    t=0.0
    for s in scores:
        lc=lognorm(s,1.0,0.42)
        lw=math.log(0.5*math.exp(lognorm(s,1.72,0.38))+0.5*math.exp(lognorm(s,-0.45,0.72)))
        t+=lc-lw
    return t + DIV*(nvar-1)
DIV=0.8

class Pool:
    def __init__(self,q):
        self.by=collections.defaultdict(list)
        for s in q['samples']: self.by[s['variant']].append(s)
        for v in self.by: random.shuffle(self.by[v])
        self.idx=collections.Counter()
    def avail(self,v): return self.idx[v]<len(self.by[v])
    def draw(self,v):
        s=self.by[v][self.idx[v]]; self.idx[v]+=1; return s['answer'],s['score']

def cands(samples):
    d=collections.defaultdict(list); vs=collections.defaultdict(set)
    for v,a,s in samples: d[a].append(s); vs[a].add(v)
    return {a:llr_alg(d[a],len(vs[a])) for a in d}, d, vs

def pick_alg(samples):
    c,d,vs=cands(samples)
    return max(c,key=c.get)

def confidence_alg(samples):
    c,d,vs=cands(samples)
    r=sorted(c.values(),reverse=True)
    top=r[0]; second=r[1] if len(r)>1 else -5
    return top-second, top

def run_batch(questions, budget, T=0.2, cap_v=8, base_alg=5, verbose=False):
    pools={q['id']:Pool(q) for q in questions}
    left=budget; out={}
    # phase 1: verifier topics
    alg=[q for q in questions if q['topic'] in ('algebra','geometry')]
    ver=[q for q in questions if q['topic'] not in ('algebra','geometry')]
    for q in ver:
        p=pools[q['id']]; best=None
        for i in range(cap_v):
            v=i%5
            if not p.avail(v): continue
            a,s=p.draw(v); left-=1
            if best is None or s>best[1]: best=(a,s)
            if s>T: break
        out[q['id']]=best[0]
    # phase 2: alg/geo with base then greedy
    S={q['id']:[] for q in alg}
    nxt={q['id']:0 for q in alg}
    def draw(qid):
        p=pools[qid]
        for _ in range(5):
            v=nxt[qid]%5; nxt[qid]+=1
            if p.avail(v):
                a,s=p.draw(v); S[qid].append((v,a,s)); return True
        return False
    for q in alg:
        for _ in range(base_alg):
            if left<=0: break
            if draw(q['id']): left-=1
    exhausted=set()
    while left>0 and len(exhausted)<len(alg):
        # lowest confidence margin
        best=None
        for q in alg:
            if q['id'] in exhausted: continue
            m,_=confidence_alg(S[q['id']])
            if best is None or m<best[0]: best=(m,q['id'])
        if best[0]>MARGIN_STOP: break
        qid=best[1]
        if draw(qid): left-=1
        else: exhausted.add(qid)
    for q in alg: out[q['id']]=pick_alg(S[q['id']])
    acc=collections.defaultdict(list)
    for q in questions: acc[q['topic']].append(out[q['id']]==q['correct_answer'])
    used=budget-left
    return {t:sum(v)/len(v) for t,v in acc.items()}, sum(out[q['id']]==q['correct_answer'] for q in questions)/len(questions), used
MARGIN_STOP=99
for DIV in [0.0,0.5,0.8,1.2]:
  for T in [0.2]:
    for cap_v in [6,8,10]:
      res=[]; 
      for rep in range(30):
        random.seed(rep)
        r=run_batch(qs, 6*len(qs), T=T, cap_v=cap_v)
        res.append(r)
      tops=collections.defaultdict(float)
      for r in res:
        for t,v in r[0].items(): tops[t]+=v/len(res)
      print(f"DIV={DIV} T={T} cap={cap_v} acc={sum(r[1] for r in res)/len(res):.3f} used={sum(r[2] for r in res)/len(res):.0f}", {t:round(v,3) for t,v in tops.items()})
